using EduCenterManagement.Data;using EduCenterManagement.Enums;using EduCenterManagement.ViewModels.Timetable;using Microsoft.EntityFrameworkCore;
namespace EduCenterManagement.Repositories;
public sealed class TimetableRepository(ApplicationDbContext db):ITimetableRepository { public async Task<IReadOnlyList<TimetableItemViewModel>> GetWeekAsync(int studentId,DateOnly start,DateOnly end,CancellationToken ct=default){var enrolled=db.Enrollments.AsNoTracking().Where(e=>e.StudentId==studentId&&e.Status==EnrollmentStatus.Confirmed).Select(e=>e.ClassId);var sessions=await db.ClassSessions.AsNoTracking().Where(s=>enrolled.Contains(s.ClassId)&&s.SessionDate>=start&&s.SessionDate<=end&&s.Status!=ClassSessionStatus.Cancelled).Select(s=>new TimetableItemViewModel{Date=s.SessionDate,StartsAt=s.StartsAt,EndsAt=s.EndsAt,SessionNumber=s.SessionNumber,Status=s.Status.ToString(),ClassName=s.Class.Name,SubjectName=s.Class.Subject.Name,TeacherName=s.Class.Teacher==null?"Not assigned":s.Class.Teacher.FullName}).ToListAsync(ct);var classesWithSessions=db.ClassSessions.AsNoTracking().Select(s=>s.ClassId);var schedules=await db.ClassSchedules.AsNoTracking().Where(x=>enrolled.Contains(x.ClassId)&&!classesWithSessions.Contains(x.ClassId)&&x.Class.StartDate<=end&&x.Class.EndDate>=start).Select(x=>new{x.DayOfWeek,x.TimeSlot.StartTime,x.TimeSlot.EndTime,x.Class.Name,Subject=x.Class.Subject.Name,Teacher=x.Class.Teacher==null?"Not assigned":x.Class.Teacher.FullName}).ToListAsync(ct);foreach(var s in schedules){var d=start.AddDays(s.DayOfWeek-2);if(d>=start&&d<=end) sessions.Add(new(){Date=d,StartsAt=s.StartTime,EndsAt=s.EndTime,ClassName=s.Name,SubjectName=s.Subject,TeacherName=s.Teacher,Status="Scheduled"});}return sessions.OrderBy(x=>x.Date).ThenBy(x=>x.StartsAt).ToList();} }
